package ca.yorku.eecs3311.orion.llm;

/**
 * Interface defining the contract for Large Language Model communications.
 * Maps directly to the LLMClient component in the Stage 1 UML diagram.
 */
public interface LLMClient {

    /**
     * Sends a formatted prompt to the LLM and retrieves the synthesized response.
     * 
     * @param prompt The constrained prompt generated by the PromptBuilder.
     * @return The text response from the AI model.
     * @throws Exception if the network request fails or API limits are hit.
     */
    /*@
      @ requires prompt != null && prompt.length() > 0;
      @ ensures \result != null;
      @*/
    String generate(String prompt) throws Exception;
}